/* Reset & Base */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    padding: 20px;
    color: #333;
}

.container {
    max-width: 600px;
    margin: 0 auto;
    background: #fff;
    border-radius: 16px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
    overflow: hidden;
}

/* Header */
.header {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: #fff;
    padding: 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.header h1 {
    font-size: 24px;
    font-weight: 600;
}

.stats {
    font-size: 14px;
    background: rgba(255, 255, 255, 0.2);
    padding: 8px 16px;
    border-radius: 20px;
}

.stats .separator {
    margin: 0 8px;
    opacity: 0.7;
}

/* Input Area */
.input-area {
    display: flex;
    gap: 12px;
    padding: 20px;
    background: #f8f9fa;
    border-bottom: 1px solid #eee;
}

#todo-input {
    flex: 1;
    padding: 12px 16px;
    font-size: 16px;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    outline: none;
    transition: border-color 0.2s;
}

#todo-input:focus {
    border-color: #667eea;
}

#todo-input::placeholder {
    color: #999;
}

/* Buttons */
.btn {
    padding: 12px 20px;
    font-size: 14px;
    font-weight: 500;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-primary {
    background: #667eea;
    color: #fff;
}

.btn-primary:hover {
    background: #5a6fd6;
    transform: translateY(-1px);
}

.btn-secondary {
    background: #e0e0e0;
    color: #666;
}

.btn-secondary:hover {
    background: #d0d0d0;
}

.btn-danger {
    background: #ff6b6b;
    color: #fff;
    padding: 6px 12px;
    font-size: 12px;
}

.btn-danger:hover {
    background: #ff5252;
}

.btn-edit {
    background: #4ecdc4;
    color: #fff;
    padding: 6px 12px;
    font-size: 12px;
}

.btn-edit:hover {
    #3dbdb5;
}

/* Todo List */
.todo-list {
    list-style: none;
    max-height: 60vh;
    overflow-y: auto;
}

.todo-item {
    display: flex;
    align-items: center;
    padding: 16px 20px;
    border-bottom: 1px solid #f0f0f0;
    gap: 12px;
    transition: background 0.2s;
}

.todo-item:hover {
    background: #fafafa;
}

.todo-item.completed .todo-text {
    text-decoration: line-through;
    color: #999;
}

.todo-checkbox {
    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: #667eea;
}

.todo-text {
    flex: 1;
    font-size: 16px;
    word-break: break-word;
}

.todo-description {
    flex: 1;
    font-size: 13px;
    color: #666;
    margin-left: 32px;
    margin-top: 4px;
}

.todo-actions {
    display: flex;
    gap: 8px;
    opacity: 0;
    transition: opacity 0.2s;
}

.todo-item:hover .todo-actions {
    opacity: 1;
}

.btn-edit, .btn-delete {
    padding: 6px 10px;
    font-size: 12px;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-edit {
    background: #4ecdc4;
    color: #fff;
}

.btn-edit:hover {
    background: #3dbdb5;
}

.btn-delete {
    background: #ff6b6b;
    color: #fff;
}

.btn-delete:hover {
    background: #ff5252;
}

/* Empty State */
.empty-state {
    text-align: center;
    padding: 60px 20px;
    color: #999;
}

.empty-state p {
    font-size: 18px;
    margin-bottom: 8px;
}

.empty-state .sub-text {
    font-size: 14px;
    color: #bbb;
}

.hidden {
    display: none !important;
}

/* Modal */
.modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    justify-content: center;
    align-items: center;
    z-index: 1000;
    animation: fadeIn 0.2s;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

.modal-content {
    background: #fff;
    border-radius: 12px;
    width: 90%;
    max-width: 400px;
    animation: slideUp 0.3s;
}

@keyframes slideUp {
    from {
        opacity: 0;
        transform: translateY(20px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.modal-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 20px;
    border-bottom: 1px solid #eee;
}

.modal-header h2 {
    font-size: 18px;
    color: #333;
}

.close-btn {
    background: none;
    border: none;
    font-size: 28px;
    color: #999;
    cursor: pointer;
    line-height: 1;
}

.close-btn:hover {
    color: #333;
}

.modal-body {
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.modal-body input,
.modal-body textarea {
    width: 100%;
    padding: 12px;
    font-size: 14px;
    border: 2px solid #e0e0e0;
    border-radius: 8px;
    outline: none;
    font-family: inherit;
}

.modal-body input:focus,
.modal-body textarea:focus {
    border-color: #667eea;
}

.modal-body textarea {
    resize: none;
}

.modal-footer {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    padding: 16px 20px;
    background: #f8f9fa;
}

/* Scrollbar */
.todo-list::-webkit-scrollbar {
    width: 6px;
}

.todo-list::-webkit-scrollbar-track {
    background: #f1f1f1;
}

.todo-list::-webkit-scrollbar-thumb {
    background: #ccc;
    border-radius: 3px;
}

.todo-list::-webkit-scrollbar-thumb:hover {
    background: #999;
}

// API Base URL
const API_BASE = '';

// State
let todos = [];
let editingId = null;

// DOM Elements
const todoInput = document.getElementById('todo-input');
const addBtn = document.getElementById('add-btn');
const todoList = document.getElementById('todo-list');
const emptyState = document.getElementById('empty-state');
const completedCount = document.querySelector('.completed-count');
const totalCount = document.querySelector('.total-count');
const editModal = document.getElementById('edit-modal');
const editTitle = document.getElementById('edit-title');
const editDescription = document.getElementById('edit-description');
const closeModal = document.getElementById('close-modal');
const cancelEdit = document.getElementById('cancel-edit');
const saveEdit = document.getElementById('save-edit');

// Initialize
document.addEventListener('DOMContentLoaded', () => {
    fetchTodos();
    setupEventListeners();
});

// Event Listeners
function setupEventListeners() {
    // Add todo
    addBtn.addEventListener('click', createTodo);
    todoInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') createTodo();
    });

    // Modal events
    closeModal.addEventListener('click', closeModalFunc);
    cancelEdit.addEventListener('click', closeModalFunc);
    saveEdit.addEventListener('click', saveTodoEdit);

    // Close modal on backdrop click
    editModal.addEventListener('click', (e) => {
        if (e.target === editModal) closeModalFunc();
    });

    // Close modal on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !editModal.classList.contains('hidden')) {
            closeModalFunc();
        }
    });
}

// API Functions
async function fetchTodos() {
    try {
        const response = await fetch(`${API_BASE}/todos`);
        if (!response.ok) throw new Error('Failed to fetch todos');
        todos = await response.json();
        renderTodos();
    } catch (error) {
        console.error('Error fetching todos:', error);
    }
}

async function createTodo() {
    const title = todoInput.value.trim();
    if (!title) return;

    try {
        const response = await fetch(`${API_BASE}/todos`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title })
        });

        if (!response.ok) throw new Error('Failed to create todo');

        const newTodo = await response.json();
        todos.push(newTodo);
        todoInput.value = '';
        renderTodos();
    } catch (error) {
        console.error('Error creating todo:', error);
    }
}

async function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;

    try {
        const response = await fetch(`${API_BASE}/todos/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: !todo.completed })
        });

        if (!response.ok) throw new Error('Failed to update todo');

        const updatedTodo = await response.json();
        const index = todos.findIndex(t => t.id === id);
        todos[index] = updatedTodo;
        renderTodos();
    } catch (error) {
        console.error('Error toggling todo:', error);
    }
}

async function deleteTodo(id) {
    if (!confirm('确定要删除这个任务吗？')) return;

    try {
        const response = await fetch(`${API_BASE}/todos/${id}`, {
            method: 'DELETE'
        });

        if (!response.ok) throw new Error('Failed to delete todo');

        todos = todos.filter(t => t.id !== id);
        renderTodos();
    } catch (error) {
        console.error('Error deleting todo:', error);
    }
}

function openEditModal(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;

    editingId = id;
    editTitle.value = todo.title;
    editDescription.value = todo.description || '';
    editModal.classList.remove('hidden');
    editTitle.focus();
}

function closeModalFunc() {
    editModal.classList.add('hidden');
    editingId = null;
    editTitle.value = '';
    editDescription.value = '';
}

async function saveTodoEdit() {
    if (!editingId) return;

    const title = editTitle.value.trim();
    if (!title) {
        alert('请输入任务标题');
        return;
    }

    try {
        const response = await fetch(`${API_BASE}/todos/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                title,
                description: editDescription.value.trim() || null
            })
        });

        if (!response.ok) throw new Error('Failed to update todo');

        const updatedTodo = await response.json();
        const index = todos.findIndex(t => t.id === editingId);
        todos[index] = updatedTodo;
        closeModalFunc();
        renderTodos();
    } catch (error) {
        console.error('Error saving todo:', error);
    }
}

// Render Functions
function renderTodos() {
    // Update stats
    const completed = todos.filter(t => t.completed).length;
    completedCount.textContent = `已完成: ${completed}`;
    totalCount.textContent = `总数: ${todos.length}`;

    // Show/hide empty state
    if (todos.length === 0) {
        todoList.innerHTML = '';
        emptyState.classList.remove('hidden');
        return;
    }

    emptyState.classList.add('hidden');

    // Sort: incomplete first, then by created date
    const sortedTodos = [...todos].sort((a, b) => {
        if (a.completed !== b.completed) return a.completed ? 1 : -1;
        return new Date(b.created_at) - new Date(a.created_at);
    });

    // Render list
    todoList.innerHTML = sortedTodos.map(todo => `
        <li class="todo-item ${todo.completed ? 'completed' : ''}" data-id="${todo.id}">
            <input 
                type="checkbox" 
                class="todo-checkbox" 
                ${todo.completed ? 'checked' : ''}
                onchange="toggleTodo(${todo.id})"
            >
            <div class="todo-content">
                <span class="todo-text">${escapeHtml(todo.title)}</span>
                ${todo.description ? `<div class="todo-description">${escapeHtml(todo.description)}</div>` : ''}
            </div>
            <div class="todo-actions">
                <button class="btn-edit" onclick="openEditModal(${todo.id})">编辑</button>
                <button class="btn-delete" onclick="deleteTodo(${todo.id})">删除</button>
            </div>
        </li>
    `).join('');
}

// Utility Functions
function escapeHtml(text) {
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

// Expose functions to global scope for onclick handlers
window.toggleTodo = toggleTodo;
window.deleteTodo = deleteTodo;
window.openEditModal = openEditModal;

