// API Base URL
const API_BASE = '';

// State
let todos = [];
let editingId = null;

// DOM Elements
const todoInput = document.getElementById('todo-input');
const addBtn = document.getElementById('add-btn');
const todoList = document.getElementById('todo-list');
const emptyState = document.getElementById('empty-state');
const completedCount = document.querySelector('.completed-count');
const totalCount = document.querySelector('.total-count');
const editModal = document.getElementById('edit-modal');
const editTitle = document.getElementById('edit-title');
const editDescription = document.getElementById('edit-description');
const closeModalBtn = document.getElementById('close-modal');
const cancelEditBtn = document.getElementById('cancel-edit');
const saveEditBtn = document.getElementById('save-edit');
const toastContainer = document.getElementById('toast-container');

// Initialize
document.addEventListener('DOMContentLoaded', () => {
    fetchTodos();
    setupEventListeners();
});

// Event Listeners
function setupEventListeners() {
    // Add todo
    addBtn.addEventListener('click', createTodo);
    todoInput.addEventListener('keypress', (e) => {
        if (e.key === 'Enter') createTodo();
    });

    // Modal events
    closeModalBtn.addEventListener('click', closeModal);
    cancelEditBtn.addEventListener('click', closeModal);
    saveEditBtn.addEventListener('click', saveTodoEdit);

    // Edit modal keyboard shortcuts
    editTitle.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            saveTodoEdit();
        }
    });

    editDescription.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            saveTodoEdit();
        }
    });

    // Close modal on backdrop click
    editModal.addEventListener('click', (e) => {
        if (e.target === editModal) closeModal();
    });

    // Close modal on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && !editModal.classList.contains('hidden')) {
            closeModal();
        }
    });

    // Event delegation for todo list
    todoList.addEventListener('click', handleTodoListClick);
    todoList.addEventListener('change', handleTodoListChange);
}

// Handle todo list clicks (edit, delete)
function handleTodoListClick(e) {
    const editBtn = e.target.closest('.btn-edit');
    const deleteBtn = e.target.closest('.btn-delete');

    if (editBtn) {
        const id = parseInt(editBtn.dataset.id);
        openEditModal(id);
    } else if (deleteBtn) {
        const id = parseInt(deleteBtn.dataset.id);
        deleteTodo(id);
    }
}

// Handle checkbox changes
function handleTodoListChange(e) {
    if (e.target.classList.contains('todo-checkbox')) {
        const id = parseInt(e.target.dataset.id);
        toggleTodo(id);
    }
}

// API Functions
async function fetchTodos() {
    try {
        const response = await fetch(`${API_BASE}/todos`);
        if (!response.ok) throw new Error('Failed to fetch todos');
        todos = await response.json();
        renderTodos();
    } catch (error) {
        console.error('Error fetching todos:', error);
        showToast('加载失败，请刷新页面重试', 'error');
    }
}

async function createTodo() {
    const title = todoInput.value.trim();
    if (!title) {
        showToast('请输入任务标题', 'info');
        todoInput.focus();
        return;
    }

    setLoading(addBtn, true);

    try {
        const response = await fetch(`${API_BASE}/todos`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ title })
        });

        if (!response.ok) throw new Error('Failed to create todo');

        const newTodo = await response.json();
        todos.unshift(newTodo);
        todoInput.value = '';
        renderTodos();
        showToast('任务添加成功', 'success');
    } catch (error) {
        console.error('Error creating todo:', error);
        showToast('添加失败，请重试', 'error');
    } finally {
        setLoading(addBtn, false);
    }
}

async function toggleTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;

    // Optimistic update
    const wasCompleted = todo.completed;
    todo.completed = !wasCompleted;
    renderTodos();

    try {
        const response = await fetch(`${API_BASE}/todos/${id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ completed: todo.completed })
        });

        if (!response.ok) throw new Error('Failed to update todo');

        const updatedTodo = await response.json();
        const index = todos.findIndex(t => t.id === id);
        todos[index] = updatedTodo;
        renderTodos();
    } catch (error) {
        console.error('Error toggling todo:', error);
        // Rollback on error
        todo.completed = wasCompleted;
        renderTodos();
        showToast('更新失败，请重试', 'error');
    }
}

async function deleteTodo(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;

    // Optimistic update - remove from UI immediately
    todos = todos.filter(t => t.id !== id);
    renderTodos();

    try {
        const response = await fetch(`${API_BASE}/todos/${id}`, {
            method: 'DELETE'
        });

        if (!response.ok) throw new Error('Failed to delete todo');

        showToast('任务已删除', 'success');
    } catch (error) {
        console.error('Error deleting todo:', error);
        // Restore on error
        todos.push(todo);
        todos.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
        renderTodos();
        showToast('删除失败，请重试', 'error');
    }
}

function openEditModal(id) {
    const todo = todos.find(t => t.id === id);
    if (!todo) return;

    editingId = id;
    editTitle.value = todo.title;
    editDescription.value = todo.description || '';
    editModal.classList.remove('hidden');
    editTitle.focus();

    // Select all text in input
    editTitle.select();
}

function closeModal() {
    editModal.classList.add('hidden');
    editingId = null;
    editTitle.value = '';
    editDescription.value = '';
}

async function saveTodoEdit() {
    if (!editingId) return;

    const title = editTitle.value.trim();
    if (!title) {
        showToast('请输入任务标题', 'info');
        editTitle.focus();
        return;
    }

    setLoading(saveEditBtn, true);

    try {
        const response = await fetch(`${API_BASE}/todos/${editingId}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                title,
                description: editDescription.value.trim() || null
            })
        });

        if (!response.ok) throw new Error('Failed to update todo');

        const updatedTodo = await response.json();
        const index = todos.findIndex(t => t.id === editingId);
        todos[index] = updatedTodo;
        closeModal();
        renderTodos();
        showToast('任务更新成功', 'success');
    } catch (error) {
        console.error('Error saving todo:', error);
        showToast('保存失败，请重试', 'error');
    } finally {
        setLoading(saveEditBtn, false);
    }
}

// Render Functions
function renderTodos() {
    // Update stats
    const completed = todos.filter(t => t.completed).length;
    completedCount.textContent = `已完成: ${completed}`;
    totalCount.textContent = `总数: ${todos.length}`;

    // Show/hide empty state
    if (todos.length === 0) {
        todoList.innerHTML = '';
        emptyState.classList.remove('hidden');
        return;
    }

    emptyState.classList.add('hidden');

    // Sort: incomplete first (by created date desc), then completed (by updated date desc)
    const sortedTodos = [...todos].sort((a, b) => {
        if (a.completed !== b.completed) return a.completed ? 1 : -1;
        return new Date(b.created_at) - new Date(a.created_at);
    });

    // Render list
    todoList.innerHTML = sortedTodos.map(todo => `
        <li class="todo-item ${todo.completed ? 'completed' : ''}" data-id="${todo.id}">
            <div class="todo-checkbox-wrapper">
                <input
                    type="checkbox"
                    class="todo-checkbox"
                    ${todo.completed ? 'checked' : ''}
                    data-id="${todo.id}"
                >
                <div class="todo-checkbox-custom"></div>
            </div>
            <div class="todo-content">
                <span class="todo-text">${escapeHtml(todo.title)}</span>
                ${todo.description ? `<div class="todo-description">${escapeHtml(todo.description)}</div>` : ''}
                <div class="todo-meta">
                    ${formatDate(todo.created_at)}
                </div>
            </div>
            <div class="todo-actions">
                <button class="btn-edit" data-id="${todo.id}">编辑</button>
                <button class="btn-delete" data-id="${todo.id}">删除</button>
            </div>
        </li>
    `).join('');
}

// Utility Functions
function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function formatDate(dateString) {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return '刚刚';
    if (diffMins < 60) return `${diffMins}分钟前`;
    if (diffHours < 24) return `${diffHours}小时前`;
    if (diffDays < 7) return `${diffDays}天前`;

    return date.toLocaleDateString('zh-CN', {
        month: 'short',
        day: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}

function setLoading(button, loading) {
    if (loading) {
        button.classList.add('loading');
        button.disabled = true;
    } else {
        button.classList.remove('loading');
        button.disabled = false;
    }
}

function showToast(message, type = 'info') {
    const toast = document.createElement('div');
    toast.className = `toast ${type}`;
    toast.textContent = message;

    toastContainer.appendChild(toast);

    // Auto remove after 3 seconds
    setTimeout(() => {
        toast.classList.add('removing');
        setTimeout(() => {
            toast.remove();
        }, 300);
    }, 3000);
}

// Expose functions for any external needs
window.getTodos = () => todos;

