/**
 * Base62 编码/解码工具
 * 字符集: 0-9, a-z, A-Z (共62个字符)
 */
const BASE62_CHARS = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

/**
 * 将数字编码为 base62 字符串
 * @param {number} num - 要编码的数字
 * @returns {string} base62 编码结果
 */
export function encode(num) {
  if (num === 0) return BASE62_CHARS[0];

  let result = '';
  let n = Math.abs(num);

  while (n > 0) {
    result = BASE62_CHARS[n % 62] + result;
    n = Math.floor(n / 62);
  }

  return result;
}

/**
 * 将 base62 字符串解码为数字
 * @param {string} str - base62 字符串
 * @returns {number} 解码后的数字
 */
export function decode(str) {
  let result = 0;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const index = BASE62_CHARS.indexOf(char);

    if (index === -1) {
      throw new Error(`Invalid base62 character: ${char}`);
    }

    result = result * 62 + index;
  }

  return result;
}

/**
 * 数据库模块 - 使用 SQLite 存储 URL 映射
 */
import Database from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';
import { encode } from './base62.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// 默认数据库路径
const DEFAULT_DB_PATH = path.join(__dirname, '..', 'data', 'urls.db');

let db = null;

/**
 * 初始化数据库连接
 * @param {string} dbPath - 数据库文件路径
 * @returns {Database} 数据库实例
 */
export function initDatabase(dbPath = DEFAULT_DB_PATH) {
  if (db) return db;

  // 确保数据目录存在
  const fs = await import('fs');
  const dbDir = path.dirname(dbPath);
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }

  db = new Database(dbPath);

  // 创建表
  db.exec(`
    CREATE TABLE IF NOT EXISTS urls (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      short_code TEXT UNIQUE NOT NULL,
      original_url TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );

    CREATE INDEX IF NOT EXISTS idx_short_code ON urls(short_code);
  `);

  return db;
}

/**
 * 关闭数据库连接
 */
export function closeDatabase() {
  if (db) {
    db.close();
    db = null;
  }
}

/**
 * 缩短 URL
 * @param {string} url - 原始 URL
 * @returns {object} 包含 short_code 和 original_url 的对象
 */
export function shortenUrl(url) {
  const database = db || initDatabase();

  // 检查 URL 是否已存在
  const existing = database.prepare('SELECT * FROM urls WHERE original_url = ?').get(url);
  if (existing) {
    return {
      shortCode: existing.short_code,
      originalUrl: existing.original_url,
      isNew: false
    };
  }

  // 插入新记录
  const stmt = database.prepare('INSERT INTO urls (original_url) VALUES (?)');
  const result = stmt.run(url);

  // 生成短码
  const shortCode = encode(result.lastInsertRowid);

  // 更新短码
  database.prepare('UPDATE urls SET short_code = ? WHERE id = ?').run(shortCode, result.lastInsertRowid);

  return {
    shortCode,
    originalUrl: url,
    isNew: true
  };
}

/**
 * 还原 URL
 * @param {string} shortCode - 短码
 * @returns {object|null} 包含 original_url 的对象，或 null
 */
export function expandUrl(shortCode) {
  const database = db || initDatabase();

  const row = database.prepare('SELECT * FROM urls WHERE short_code = ?').get(shortCode);

  if (!row) {
    return null;
  }

  return {
    shortCode: row.short_code,
    originalUrl: row.original_url,
    createdAt: row.created_at
  };
}

/**
 * 获取所有 URL
 * @returns {Array} URL 列表
 */
export function listUrls() {
  const database = db || initDatabase();

  return database.prepare('SELECT * FROM urls ORDER BY created_at DESC').all();
}

