#!/usr/bin/env node

/**
 * URL Shortener CLI
 */
import { Command } from 'commander';
import { shortenUrl, expandUrl, listUrls, initDatabase, closeDatabase } from '../src/index.js';

const program = new Command();

program
  .name('url-shorten')
  .description('URL 缩短器 CLI 工具')
  .version('1.0.0');

program
  .command('shorten <url>')
  .description('缩短 URL')
  .option('-b, --base <domain>', '基础域名 (用于显示完整短链接)', '')
  .action((url, options) => {
    try {
      const result = shortenUrl(url);

      if (options.base) {
        const fullUrl = options.base.endsWith('/') 
          ? `${options.base}${result.shortCode}`
          : `${options.base}/${result.shortCode}`;
        console.log(`短链接: ${fullUrl}`);
      } else {
        console.log(`短码: ${result.shortCode}`);
      }

      if (result.isNew) {
        console.log(`原链接: ${result.originalUrl}`);
        console.log('✓ 新建成功');
      } else {
        console.log(`原链接: ${result.originalUrl}`);
        console.log('ℹ 该 URL 已存在');
      }
    } catch (error) {
      console.error('错误:', error.message);
      process.exit(1);
    } finally {
      closeDatabase();
    }
  });

program
  .command('expand <code>')
  .description('还原 URL (根据短码获取原链接)')
  .action((code) => {
    try {
      const result = expandUrl(code);

      if (result) {
        console.log(`原链接: ${result.originalUrl}`);
        console.log(`创建时间: ${result.createdAt}`);
      } else {
        console.log('未找到对应的 URL');
        process.exit(1);
      }
    } catch (error) {
      console.error('错误:', error.message);
      process.exit(1);
    } finally {
      closeDatabase();
    }
  });

program
  .command('list')
  .description('列出所有 URL')
  .option('-l, --limit <number>', '限制显示数量', '20')
  .action((options) => {
    try {
      const urls = listUrls();
      const limit = parseInt(options.limit, 10);

      if (urls.length === 0) {
        console.log('暂无数据');
        return;
      }

      console.log(`\n共 ${urls.length} 条记录:\n`);
      console.log('短码\t\t原链接');
      console.log('-'.repeat(60));

      urls.slice(0, limit).forEach(row => {
        const url = row.original_url.length > 50 
          ? row.original_url.substring(0, 47) + '...' 
          : row.original_url;
        console.log(`${row.short_code}\t\t${url}`);
      });

      if (urls.length > limit) {
        console.log(`\n... 还有 ${urls.length - limit} 条记录`);
      }
    } catch (error) {
      console.error('错误:', error.message);
      process.exit(1);
    } finally {
      closeDatabase();
    }
  });

program.parse();

