console.log('🧪 开始测试 URL Shortener\n');

// 清理测试目录
function cleanup() {
  const testDir = path.dirname(TEST_DB_PATH);
  if (fs.existsSync(testDir)) {
    fs.rmSync(testDir, { recursive: true });
  }
}

// Base62 测试
