console.log('-'.repeat(40));

assert.equal(encode(0), '0', 'encode(0) 应该返回 "0"');
console.log('✓ encode(0) = "0"');

assert.equal(encode(1), '1', 'encode(1) 应该返回 "1"');
console.log('✓ encode(1) = "1"');

assert.equal(encode(10), 'a', 'encode(10) 应该返回 "a"');
console.log('✓ encode(10) = "a"');

assert.equal(encode(61), 'Z', 'encode(61) 应该返回 "Z"');
console.log('✓ encode(61) = "Z"');

assert.equal(encode(62), '10', 'encode(62) 应该返回 "10"');
console.log('✓ encode(62) = "10"');

assert.equal(encode(12345), 'd7C', 'encode(12345) 应该返回 "d7C"');
console.log('✓ encode(12345) = "d7C"');

// Decode 测试
console.log('\n📝 Base62 解码测试');
console.log('-'.repeat(40));

assert.equal(decode('0'), 0, 'decode("0") 应该返回 0');
console.log('✓ decode("0") = 0');

assert.equal(decode('Z'), 61, 'decode("Z") 应该返回 61');
console.log('✓ decode("Z") = 61');

assert.equal(decode('10'), 62, 'decode("10") 应该返回 62');
console.log('✓ decode("10") = 62');

assert.equal(decode('d7C'), 12345, 'decode("d7C") 应该返回 12345');
console.log('✓ decode("d7C") = 12345');

// 编码/解码往返测试
console.log('\n📝 编码/解码往返测试');
console.log('-'.repeat(40));

const testNumbers = [1, 100, 1000, 10000, 100000, 999999];
testNumbers.forEach(num => {
  const encoded = encode(num);
  const decoded = decode(encoded);
  assert.equal(decoded, num, `往返测试失败: ${num} -> ${encoded} -> ${decoded}`);
  console.log(`✓ ${num} -> ${encoded} -> ${decoded}`);
});

// 数据库测试
console.log('\n📝 数据库功能测试');
console.log('-'.repeat(40));

cleanup();

// 初始化测试数据库
initDatabase(TEST_DB_PATH);

// 测试缩短 URL
const result1 = shortenUrl('https://example.com');
assert.ok(result1.shortCode, '应该返回短码');
assert.equal(result1.originalUrl, 'https://example.com');
assert.equal(result1.isNew, true);
console.log(`✓ 缩短 URL: https://example.com -> ${result1.shortCode}`);

// 测试重复 URL
const result2 = shortenUrl('https://example.com');
assert.equal(result2.shortCode, result1.shortCode, '重复 URL 应该返回相同短码');
assert.equal(result2.isNew, false);
console.log(`✓ 重复 URL 返回相同短码: ${result2.shortCode}`);

// 测试还原 URL
const expanded = expandUrl(result1.shortCode);
assert.ok(expanded, '应该能找到 URL');
assert.equal(expanded.originalUrl, 'https://example.com');
console.log(`✓ 还原 URL: ${result1.shortCode} -> ${expanded.originalUrl}`);

// 测试不存在的短码
const notFound = expandUrl('notexist');
assert.equal(notFound, null, '不存在的短码应该返回 null');
console.log('✓ 不存在的短码返回 null');

// 测试列表
const urls = listUrls();
assert.equal(urls.length, 1, '应该有 1 条记录');
console.log(`✓ 列表查询: ${urls.length} 条记录`);

// 添加更多 URL
shortenUrl('https://google.com');
shortenUrl('https://github.com');
const allUrls = listUrls();
assert.equal(allUrls.length, 3, '应该有 3 条记录');
console.log(`✓ 添加更多 URL 后: ${allUrls.length} 条记录`);

// 关闭数据库
closeDatabase();

// 清理
cleanup();

console.log('\n' + '='.repeat(40));
console.log('✅ 所有测试通过！');
console.log('='.repeat(40));

