  const updateStmt = database.prepare('UPDATE urls SET short_code = ? WHERE id = ?');

  const transaction = database.transaction(() => {
    // 先插入临时短码
    const result = insertStmt.run(url, 'tmp');
    const id = result.lastInsertRowid;

    // 生成真正的短码
