/**
 * Base62 编码器
 * 字符集: 0-9, a-z, A-Z (共62个字符)
 */

const BASE62_CHARS = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';

/**
 * 将数字编码为 Base62 字符串
 * @param {number} num - 要编码的非负整数
 * @returns {string} Base62 编码结果
 */
export function encode(num) {
  if (typeof num !== 'number' || num < 0 || !Number.isInteger(num)) {
    throw new Error('Input must be a non-negative integer');
  }

  if (num === 0) return BASE62_CHARS[0];

  let result = '';
  let n = num;

  while (n > 0) {
    result = BASE62_CHARS[n % 62] + result;
    n = Math.floor(n / 62);
  }

  return result;
}

/**
 * 将 Base62 字符串解码为数字
 * @param {string} str - Base62 字符串
 * @returns {number} 解码后的数字
 */
export function decode(str) {
  if (typeof str !== 'string' || str.length === 0) {
    throw new Error('Input must be a non-empty string');
  }

  let result = 0;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const index = BASE62_CHARS.indexOf(char);

    if (index === -1) {
      throw new Error(`Invalid Base62 character: ${char}`);
    }

    result = result * 62 + index;
  }

  return result;
}

/**
 * 数据库模块 - SQLite 存储
 */
import Database from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';
import fs from 'fs';
import { encode } from './encoder.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const DEFAULT_DB_PATH = path.join(__dirname, '..', 'data', 'urls.db');

let db = null;

/**
 * 初始化数据库
 * @param {string} dbPath - 数据库文件路径
 */
export function initDatabase(dbPath = DEFAULT_DB_PATH) {
  if (db) return db;

  const dbDir = path.dirname(dbPath);
  if (!fs.existsSync(dbDir)) {
    fs.mkdirSync(dbDir, { recursive: true });
  }

  db = new Database(dbPath);

  db.exec(`
    CREATE TABLE IF NOT EXISTS urls (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      short_code TEXT UNIQUE NOT NULL,
      original_url TEXT NOT NULL,
      title TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      expires_at DATETIME,
      click_count INTEGER DEFAULT 0
    );

    CREATE INDEX IF NOT EXISTS idx_short_code ON urls(short_code);
    CREATE INDEX IF NOT EXISTS idx_original_url ON urls(original_url);
  `);

  return db;
}

/**
 * 获取数据库实例
 */
export function getDb() {
  return db || initDatabase();
}

/**
 * 关闭数据库连接
 */
export function closeDatabase() {
  if (db) {
    db.close();
    db = null;
  }
}

/**
 * 缩短 URL
 * @param {string} url - 原始 URL
 * @param {string} [title] - 可选标题
 * @returns {object} 结果对象
 */
export function shortenUrl(url, title = null) {
  const database = getDb();

  // 检查是否已存在
  const existing = database.prepare('SELECT * FROM urls WHERE original_url = ?').get(url);
  if (existing) {
    return { ...existing, isNew: false };
  }

  // 使用事务插入
  const insert = database.prepare('INSERT INTO urls (original_url, short_code, title) VALUES (?, ?, ?)');
  const update = database.prepare('UPDATE urls SET short_code = ? WHERE id = ?');

  const transaction = database.transaction(() => {
    const result = insert.run(url, 'tmp', title);
    const id = result.lastInsertRowid;
    const shortCode = encode(id);
    update.run(shortCode, id);
    return { id, shortCode };
  });

  const { id, shortCode } = transaction();

  return {
    id,
    short_code: shortCode,
    original_url: url,
    title,
    created_at: new Date().toISOString(),
    click_count: 0,
    isNew: true
  };
}

/**
 * 展开短码
 * @param {string} shortCode - 短码
 * @returns {object|null} URL 记录
 */
export function expandUrl(shortCode) {
  const database = getDb();

  const row = database.prepare('SELECT * FROM urls WHERE short_code = ?').get(shortCode);

  if (!row) return null;

  // 更新点击计数
  database.prepare('UPDATE urls SET click_count = click_count + 1 WHERE id = ?').run(row.id);

  return row;
}

/**
 * 获取所有 URL
 * @param {object} options - 查询选项
 * @returns {Array} URL 列表
 */
export function listUrls(options = {}) {
  const database = getDb();
  const { limit = 100, offset = 0 } = options;

  return database.prepare('SELECT * FROM urls ORDER BY created_at DESC LIMIT ? OFFSET ?').all(limit, offset);
}

/**
 * 删除 URL
 * @param {string} shortCode - 短码
 * @returns {boolean} 是否删除成功
 */
export function deleteUrl(shortCode) {
  const database = getDb();
  const result = database.prepare('DELETE FROM urls WHERE short_code = ?').run(shortCode);
  return result.changes > 0;
}

/**
 * 获取统计信息
 * @returns {object} 统计数据
 */
export function getStats() {
  const database = getDb();

  const total = database.prepare('SELECT COUNT(*) as count FROM urls').get();
  const totalClicks = database.prepare('SELECT SUM(click_count) as total FROM urls').get();

  return {
    totalUrls: total.count,
    totalClicks: totalClicks.total || 0
  };
}

