import chalk from 'chalk';
import { shortenUrl } from '../db.js';

/**
 * 执行 shorten 命令
 * @param {string} url - 要缩短的 URL
 * @param {object} options - 命令选项
 */
export function shorten(url, options = {}) {
  const { json, title } = options;

  try {
    // 验证 URL
    if (!url) {
      console.error(chalk.red('错误: 请提供要缩短的 URL'));
      process.exit(1);
    }

    // 简单的 URL 验证
    try {
      new URL(url);
    } catch {
      console.error(chalk.red('错误: 无效的 URL 格式'));
      process.exit(1);
    }

    const result = shortenUrl(url, title);

    if (json) {
      console.log(JSON.stringify(result, null, 2));
      return;
    }

    if (result.isNew) {
      console.log(chalk.green('✓ URL 已缩短:'));
    } else {
      console.log(chalk.yellow('ℹ URL 已存在:'));
    }

    console.log();
    console.log(`  ${chalk.bold('短码:')} ${chalk.cyan(result.short_code)}`);
    console.log(`  ${chalk.bold('原链:')} ${result.original_url}`);

    if (result.title) {
      console.log(`  ${chalk.bold('标题:')} ${result.title}`);
    }

    if (options.base) {
      const baseUrl = options.base.endsWith('/') ? options.base : `${options.base}/`;
      console.log(`  ${chalk.bold('完整:')} ${chalk.blue(baseUrl + result.short_code)}`);
    }

  } catch (error) {
    console.error(chalk.red(`错误: ${error.message}`));
    process.exit(1);
  }
}

/**
 * expand 命令 - 展开短码
 */
import chalk from 'chalk';
import { expandUrl } from '../db.js';

/**
 * 执行 expand 命令
 * @param {string} code - 短码
 * @param {object} options - 命令选项
 */
export function expand(code, options = {}) {
  const { json } = options;

  try {
    if (!code) {
      console.error(chalk.red('错误: 请提供短码'));
      process.exit(1);
    }

    const result = expandUrl(code);

    if (!result) {
      if (json) {
        console.log(JSON.stringify({ error: 'Short code not found' }, null, 2));
      } else {
        console.error(chalk.red(`错误: 短码 "${code}" 不存在`));
      }
      process.exit(1);
    }

    if (json) {
      console.log(JSON.stringify(result, null, 2));
      return;
    }

    console.log(chalk.green('✓ 找到原始 URL:'));
    console.log();
    console.log(`  ${chalk.bold('原链:')} ${chalk.blue(result.original_url)}`);
    console.log(`  ${chalk.bold('短码:')} ${chalk.cyan(result.short_code)}`);
    console.log(`  ${chalk.bold('点击:')} ${result.click_count || 0} 次`);

    if (result.title) {
      console.log(`  ${chalk.bold('标题:')} ${result.title}`);
    }

    if (result.created_at) {
      console.log(`  ${chalk.bold('创建:')} ${new Date(result.created_at).toLocaleString('zh-CN')}`);
    }

  } catch (error) {
    console.error(chalk.red(`错误: ${error.message}`));
    process.exit(1);
  }
}

/**
 * list 命令 - 列出所有 URL
 */
import chalk from 'chalk';
import Table from 'cli-table3';
import { listUrls, getStats, closeDatabase } from '../db.js';

/**
 * 执行 list 命令
 * @param {object} options - 命令选项
 */
export function list(options = {}) {
  const { json, limit = 20 } = options;

  try {
    const urls = listUrls({ limit });
    const stats = getStats();

    if (json) {
      console.log(JSON.stringify({ urls, stats }, null, 2));
      return;
    }

    if (urls.length === 0) {
      console.log(chalk.yellow('暂无 URL 记录'));
      console.log(chalk.gray('使用 url-shortener shorten <url> 添加第一条记录'));
      return;
    }

    // 创建表格
    const table = new Table({
      head: [
        chalk.bold.cyan('短码'),
        chalk.bold.cyan('原始 URL'),
        chalk.bold.cyan('点击'),
        chalk.bold.cyan('创建时间')
      ],
      colWidths: [10, 50, 8, 20],
      wordWrap: true
    });

    urls.forEach(row => {
      const url = row.original_url.length > 45 
        ? row.original_url.substring(0, 42) + '...'
        : row.original_url;

      const date = row.created_at 
        ? new Date(row.created_at).toLocaleDateString('zh-CN')
        : '-';

      table.push([
        chalk.green(row.short_code),
        url,
        row.click_count || 0,
        date
      ]);
    });

    console.log();
    console.log(table.toString());
    console.log();
    console.log(chalk.gray(`共 ${stats.totalUrls} 条记录，累计 ${stats.totalClicks} 次点击`));

  } catch (error) {
    console.error(chalk.red(`错误: ${error.message}`));
    process.exit(1);
  }
}

#!/usr/bin/env node

/**
 * URL Shortener CLI 入口
 */
import { Command } from 'commander';
import { shorten } from '../src/commands/shorten.js';
import { expand } from '../src/commands/expand.js';
import { list } from '../src/commands/list.js';
import { closeDatabase } from '../src/db.js';

const program = new Command();

program
  .name('url-shortener')
  .description('URL 缩短器 CLI 工具')
  .version('1.0.0')
  .hook('postAction', () => {
    closeDatabase();
  });

// shorten 命令
program
  .command('shorten <url>')
  .description('缩短 URL')
  .option('-t, --title <title>', '为 URL 添加标题')
  .option('-b, --base <domain>', '基础域名，用于生成完整短链接')
  .option('--json', '输出 JSON 格式')
  .action(shorten);

// expand 命令
program
  .command('expand <code>')
  .description('展开短码，获取原始 URL')
  .option('--json', '输出 JSON 格式')
  .action(expand);

// list 命令
program
  .command('list')
  .description('列出所有 URL')
  .option('-l, --limit <number>', '限制显示数量', '20')
  .option('--json', '输出 JSON 格式')
  .action(list);

program.parse();

